insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'0d7bcb6f-07ef-562e-8d0b-39b77155323f',E'Anexo I. Metadatos Referenciales de la Norma Técnica para la elaboración de Metadatos de los Procesos de Producción de Información Estadística y Geográfica',E'METADATOS-I',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Metadatos referenciales',E'Condición de llenado',E'DDI',E'SDMX']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Vigente/anexos_I_ntmppieg.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'da9151df-5131-5c85-86b7-42d8d6c5c28f',E'Anexo I · 52 elementos referenciales · pág. 1',E'<section><p>El presente anexo tiene por objeto listar cada uno de los elementos de la especificación de Metadatos Referenciales para la descripción estandarizada de los aspectos conceptuales, metodológicos y de calidad de los Procesos de Producción de información estadística y geográfica, así como su respectiva condición de llenado. Esta especificación de metadatos fue adaptada a partir de la Iniciativa de Documentación de Datos (DDI, por sus siglas en inglés) versión 2.0 y la estructura de metadatos del estándar Statistical Data and Metadata Exchange (SDMX) para el Sistema Estadístico Europeo (ESMS) 2.0.</p><div class="overflow-x-auto"><table><thead><tr><th>Número</th><th>Sección</th><th>Apartado</th><th>Elemento</th><th>Condición de llenado</th></tr></thead><tbody><tr><td>1</td><td>Identificación del documento de metadatos</td><td>Creación o actualización del documento de metadatos</td><td>Productor del metadato</td><td>Obligatorio</td></tr><tr><td>2</td><td>Identificación del documento de metadatos</td><td>Creación o actualización del documento de metadatos</td><td>Fecha de actualización del metadato</td><td>Obligatorio</td></tr><tr><td>3</td><td>Identificación del documento de metadatos</td><td>Creación o actualización del documento de metadatos</td><td>Actualización de los metadatos</td><td>Obligatorio</td></tr><tr><td>4</td><td>Proceso de Producción documentado</td><td>Datos de identificación</td><td>Número de identificación</td><td>Obligatorio</td></tr><tr><td>5</td><td>Proceso de Producción documentado</td><td>Datos de identificación</td><td>Proceso de Producción</td><td>Obligatorio</td></tr><tr><td>6</td><td>Proceso de Producción documentado</td><td>Datos de identificación</td><td>Programa de Información</td><td>Obligatorio</td></tr