td>Obligatorio</td></tr><tr><td>47</td><td>Características del Proceso de Producción</td><td>Aseguramiento de la calidad</td><td>Accesibilidad: Interpretación de la información</td><td>Obligatorio</td></tr><tr><td>48</td><td>Características del Proceso de Producción</td><td>Aseguramiento de la calidad</td><td>Puntualidad: Incorporación en Calendario de difusión</td><td>Obligatorio</td></tr><tr><td>49</td><td>Características del Proceso de Producción</td><td>Aseguramiento de la calidad</td><td>Puntualidad: Fechas de publicación comprometidas</td><td>Recomendado</td></tr><tr><td>50</td><td>Características del Proceso de Producción</td><td>Aseguramiento de la calidad</td><td>Oportunidad: Parámetro de referencia y oportunidad observada</td><td>Obligatorio</td></tr><tr><td>51</td><td>Características del Proceso de Producción</td><td>Aseguramiento de la calidad</td><td>Coherencia y comparabilidad: Comparabilidad temporal y geográfica</td><td>Obligatorio</td></tr><tr><td>52</td><td>Características del Proceso de Producción</td><td>Aseguramiento de la calidad</td><td>Veracidad: Precisión y confiabilidad estadística y Exactitud geográfica</td><td>Obligatorio</td></tr></tbody></table></div></section>',E'anexo',1,E'Anexo de la Norma Técnica de Metadatos',E'Metadatos referenciales',E'Anexo I · 52 elementos referenciales',E'0d7bcb6f-07ef-562e-8d0b-39b77155323f') on conflict(id) do nothing;
